pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy >= 0);
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        try c.owned() {} catch { return; }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue(afterOwner == beforeOwner);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
